/**
 * Background-job handlers — invoked by AppJobRoom (worker.ts) for every job
 * picked up from the queue. See docs/ARCHITECTURE.md ("Synthetic data
 * import") for the full design rationale.
 *
 * `import-synthetic-events` loads the canonical dataset generated by
 * scripts/generate-dataset.mjs (committed at src/data/synthetic-auth-
 * events.json) into the `authEvents` collection. Both this job and the
 * import run as a background job (not a server action) because bulk
 * inserting hundreds-to-thousands of rows is exactly the case the
 * background-jobs guide calls out — "bulk imports" — and a server action
 * must finish inside one HTTP response.
 *
 * Idempotency (required by the approved plan): every row is upserted with
 * `tools.create(collection, data, recordId)` using the dataset's stable
 * `eventId` AS the DeepSpace recordId. Per the SDK docs, passing a known
 * `recordId` to `create` merges onto the existing row if one already exists
 * instead of creating a duplicate — so re-running this job (including after
 * regenerating a larger dataset with the same seed) never duplicates a row
 * or leaves two rows for one event.
 */

import type { Job, JobContext } from 'deepspace/worker'
import { createActionTools } from './server/record-tools.js'
import { computeStatScores, type AuthEventInput } from './lib/anomaly-detection.js'
import type { Env } from '../worker.js'
import syntheticDataset from './data/synthetic-auth-events.json'
import mlScoresDataset from './data/ml-scores.json'

interface SyntheticEvent {
  eventId: string
  datasetVersion: string
  timestamp: number
  actorId: string
  sourceIp: string
  country: string
  city: string
  device: string
  eventType: string
  success: number
  groundTruthAnomaly: number
  groundTruthReason: string
}

interface ImportSyntheticEventsPayload {
  /** How many of the dataset's events to import. Defaults to all of them. */
  limit?: number
}

const dataset = syntheticDataset as {
  datasetVersion: string
  count: number
  anomalyCount: number
  events: SyntheticEvent[]
}

async function importSyntheticEvents(
  ctx: JobContext,
  env: Env,
  payload: ImportSyntheticEventsPayload,
): Promise<unknown> {
  const tools = createActionTools(env, env.OWNER_USER_ID, '')
  const events = payload.limit ? dataset.events.slice(0, payload.limit) : dataset.events
  const total = events.length

  let imported = 0
  let failed = 0
  const errors: string[] = []

  for (let i = 0; i < total; i++) {
    if (ctx.signal.aborted) break
    const e = events[i]
    const { eventId, ...data } = e
    const result = await tools.create('authEvents', data, eventId)
    if (result.success) {
      imported += 1
    } else {
      failed += 1
      if (errors.length < 10) errors.push(`${eventId}: ${result.error}`)
    }

    if (i % 25 === 0 || i === total - 1) {
      ctx.progress((i + 1) / total, `${i + 1}/${total} events upserted`)
    }
  }

  return {
    datasetVersion: dataset.datasetVersion,
    totalInDataset: total,
    imported,
    failed,
    errors,
  }
}

/**
 * Recomputes every authEvents row's `statAnomalyScore`/`statReasons` from
 * scratch using the pure, deterministic rules in
 * src/lib/anomaly-detection.ts. Runs as a background job (not a server
 * action) for the same reason the import does: querying and patching
 * hundreds-to-thousands of rows can exceed a single HTTP response.
 *
 * Idempotent by construction — `computeStatScores` is a pure function, so
 * recomputing against unchanged data always reproduces the same scores.
 * There's nothing to "duplicate": this only patches existing rows, it
 * never creates any.
 */
async function recomputeStatScores(ctx: JobContext, env: Env): Promise<unknown> {
  const tools = createActionTools(env, env.OWNER_USER_ID, '')

  const queryResult = await tools.query<{
    actorId: string
    timestamp: number
    country: string
    city: string
    device: string
    eventType: string
    success: number
    statReasons?: string[]
  }>('authEvents', { limit: 5000 })
  if (!queryResult.success) {
    throw new Error(`Failed to load authEvents: ${queryResult.error}`)
  }

  const inputs: AuthEventInput[] = queryResult.data.records.map((r) => ({
    recordId: r.recordId,
    actorId: r.data.actorId,
    timestamp: r.data.timestamp,
    country: r.data.country,
    city: r.data.city,
    device: r.data.device,
    eventType: r.data.eventType,
    success: r.data.success,
  }))

  const results = computeStatScores(inputs)
  const total = results.length
  let updated = 0
  let failed = 0
  const errors: string[] = []

  for (let i = 0; i < total; i++) {
    if (ctx.signal.aborted) break
    const r = results[i]
    const outcome = await tools.update('authEvents', r.recordId, {
      statAnomalyScore: r.statAnomalyScore,
      statReasons: r.statReasons,
    })
    if (outcome.success) updated += 1
    else {
      failed += 1
      if (errors.length < 10) errors.push(`${r.recordId}: ${outcome.error}`)
    }

    if (i % 25 === 0 || i === total - 1) {
      ctx.progress((i + 1) / total, `${i + 1}/${total} events scored`)
    }
  }

  const flagged = results.filter((r) => r.statReasons.length > 0).length
  return { totalEvents: total, updated, failed, flagged, errors }
}

interface MlScoreEntry {
  eventId: string
  mlAnomalyScore: number
  mlIsOutlier: number
}

const mlScores = mlScoresDataset as {
  modelVersion: string
  datasetVersion: string
  generatedAt: string
  events: MlScoreEntry[]
}

/**
 * Imports the offline Isolation Forest scores (scripts/ml/
 * train_and_evaluate.py's committed output, src/data/ml-scores.json) onto
 * the matching `authEvents` rows, keyed by the same stable `eventId` the
 * synthetic import used as the recordId.
 *
 * Idempotent and non-corrupting by construction, not just by convention:
 * `tools.update` can only ever patch an EXISTING row (the SDK's own
 * `records.update` refuses "no record … — updates never create" if the id
 * doesn't exist yet — see src/server/record-tools.ts), so a repeat run can
 * never create a duplicate. And because the patch object here only ever
 * contains `mlAnomalyScore`/`mlIsOutlier`, the envelope-merge semantics of
 * `update` (patch fields are merged onto the existing row, not a full
 * overwrite) mean `statAnomalyScore`/`statReasons` — written by a
 * completely separate job — are never touched.
 */
async function importMlScores(ctx: JobContext, env: Env): Promise<unknown> {
  const tools = createActionTools(env, env.OWNER_USER_ID, '')
  const total = mlScores.events.length

  let updated = 0
  let failed = 0
  const errors: string[] = []

  for (let i = 0; i < total; i++) {
    if (ctx.signal.aborted) break
    const e = mlScores.events[i]
    const outcome = await tools.update('authEvents', e.eventId, {
      mlAnomalyScore: e.mlAnomalyScore,
      mlIsOutlier: e.mlIsOutlier,
    })
    if (outcome.success) updated += 1
    else {
      failed += 1
      if (errors.length < 10) errors.push(`${e.eventId}: ${outcome.error}`)
    }

    if (i % 25 === 0 || i === total - 1) {
      ctx.progress((i + 1) / total, `${i + 1}/${total} ML scores applied`)
    }
  }

  const flagged = mlScores.events.filter((e) => e.mlIsOutlier === 1).length
  return {
    modelVersion: mlScores.modelVersion,
    datasetVersion: mlScores.datasetVersion,
    totalInDataset: total,
    updated,
    failed,
    flagged,
    errors,
  }
}

export async function runJob(job: Job, ctx: JobContext, env: Env): Promise<unknown> {
  switch (job.type) {
    case 'import-synthetic-events': {
      return importSyntheticEvents(ctx, env, (job.payload as ImportSyntheticEventsPayload) ?? {})
    }
    case 'recompute-stat-scores': {
      return recomputeStatScores(ctx, env)
    }
    case 'import-ml-scores': {
      return importMlScores(ctx, env)
    }
    default:
      throw new Error(`Unknown job type: ${job.type}`)
  }
}
